/*Table structure for table `care_record` */

DROP TABLE IF EXISTS `care_record`;

CREATE TABLE `care_record` (
  `record_id` bigint NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `elderly_id` bigint NOT NULL COMMENT '老人ID',
  `creator_id` bigint NOT NULL COMMENT '护工ID',
  `care_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '照料类型',
  `care_content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '照料内容',
  `care_time` datetime DEFAULT NULL COMMENT '预计照料时间',
  `start_time` datetime DEFAULT NULL COMMENT '照料开始时间',
  `approved_time` datetime DEFAULT NULL COMMENT '照料结束时间',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '状态（0待执行 1已完成 2异常）',
  `image_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '打卡图片URL',
  `remark` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '备注',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  PRIMARY KEY (`record_id`),
  KEY `idx_elderly_id` (`elderly_id`),
  KEY `idx_nurse_id` (`creator_id`),
  CONSTRAINT `fk_care_record_elderly` FOREIGN KEY (`elderly_id`) REFERENCES `elderly` (`elderly_id`),
  CONSTRAINT `fk_care_record_nurse` FOREIGN KEY (`creator_id`) REFERENCES `sys_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=4009 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='生活照料记录表';

