/*Table structure for table `service_item` */

DROP TABLE IF EXISTS `service_item`;

CREATE TABLE `service_item` (
  `item_id` bigint NOT NULL AUTO_INCREMENT COMMENT '服务项目ID',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '项目名称',
  `category` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '项目分类',
  `duration_minutes` int DEFAULT NULL COMMENT '预计耗时（分钟）',
  `price` decimal(10,2) DEFAULT NULL COMMENT '单价（元）',
  `description` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '项目详细描述',
  `image_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '项目图片路径',
  `is_active` tinyint NOT NULL DEFAULT '1' COMMENT '是否启用：1-是，0-否',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志：0-正常，1-删除',
  PRIMARY KEY (`item_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='服务项目库表';

/*Data for the table `service_item` */

insert  into `service_item`(`item_id`,`name`,`category`,`duration_minutes`,`price`,`description`,`image_url`,`is_active`,`create_by`,`create_time`,`update_by`,`update_time`,`del_flag`) values (1,'足浴','护理',30,'50.00','中药泡脚，促进血液循环','/profile/upload/2025/12/18/屏幕截图 2025-05-15 151407_20251218192225A001.png',0,NULL,'2025-12-18 11:50:05',NULL,'2026-04-01 21:30:10',0),(2,'推拿','理疗',45,'80.00','肩颈推拿，缓解肌肉紧张','/upload/service/massage.jpg',1,NULL,'2025-12-18 11:50:05',NULL,'2026-04-01 20:39:26',0),(3,'血糖监测','健康监测',10,'10.00','空腹血糖检测','/upload/service/bloodsugar.jpg',1,NULL,'2025-12-18 11:50:05',NULL,NULL,0),(4,'喂药','护理',5,'0.00','根据医嘱辅助老人按时服用药物','/profile/upload/2026/03/11/医养结合系统任务打卡图片生成（给奶奶洗脚） (2)_20260311142135A001.png',1,NULL,'2026-03-11 14:21:38',NULL,NULL,0);

/*Table structure for table `sys_chat_history` */

DROP TABLE IF EXISTS `sys_chat_history`;

CREATE TABLE `sys_chat_history` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `user_id` bigint NOT NULL COMMENT '用户 ID',
  `chat_id` varchar(36) NOT NULL COMMENT '会话ID',
  `query` text NOT NULL COMMENT '用户问题',
  `answer` text COMMENT 'AI回答',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`),
  KEY `idx_chat_id` (`chat_id`),
  KEY `idx_user_id` (`user_id`),
  CONSTRAINT `fk_chat_session` FOREIGN KEY (`chat_id`) REFERENCES `sys_chat_session` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=58 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='聊天历史记录表';

/*Data for the table `sys_chat_history` */

insert  into `sys_chat_history`(`id`,`user_id`,`chat_id`,`query`,`answer`,`create_time`) values (36,102,'dc82147f-d49c-4f34-8736-06eef83cdc55','我想给李奶奶开药该怎么操作','doctor_wang 医生，您好！\n\n在颐养管理系统中，为李奶奶开药（即开立医嘱）的操作流程如下：\n\n**操作步骤：**\n\n1.  **进入功能模块**：登录系统后，找到并进入“医嘱开立管理”模块。\n2.  **新增医嘱**：\n    *   点击页面上的 **“新增”** 按钮。\n    *   在弹出的界面中，**选择老人**（查找并选中“李奶奶”）。\n    *   填写具体的 **医嘱内容**（如诊断结果、治疗方案等）。\n    *   详细填写 **用药建议**（包括药品名称、剂量、频次、给药途径等）。\n    *   确认信息无误后，点击 **“确定”** 保存。\n\n**后续流程说明：**\n*   一旦您成功开立医嘱，系统会**自动生成**相应的用药跟踪任务。\n*   该任务会自动分配给负责李奶奶的**护工**，护工将在其终端收到提醒并执行给药操作。\n*   您可以随时点击该医嘱的 **“查看详情”**，查看护工的用药执行记录，确保治疗落实。\n\n**温馨提示：**\n如果李奶奶的病情发生变化需要调整药物，您可以使用 **“修改”** 功能更新医嘱；若需停止某项药物治疗，请使用 **“停用”** 功能将医嘱状态更为停用，切勿直接删除以保证医疗记录的完整性。\n\n如果您需要查询李奶奶的历史用药记录或过敏史以辅助开药，请告诉我，我可以帮您检索相关信息。','2026-04-16 19:00:30'),(40,1,'a3691917-17ac-4878-a479-bdb3a0070edb','测试','<think>\n好的，我现在需要处理用户的测试查询。首先，用户以管理员身份登录，所以我要确保回答符合管理层面的建议。用户的消息是“测试”，可能是在验证系统是否正常工作。\n\n根据规则，管理员可以得到管理建议，所以我应该提供一个示例回答，展示如何回应管理员的问题。同时，需要检查是否需要调用工具函数。这里用户没有具体问题，可能需要询问更多信息或提供帮助选项。\n\n另外，必须确认是否要使用current_time工具。但用户的问题不涉及时间，所以可能不需要调用。应该先询问用户具体需求，比如管理方面的哪个部分需要帮助，比如入住流程、员工排班或数据分析等，这样可以更精准地提供支持。\n\n还要确保回答简洁，用中文口语化，并鼓励用户提供更多细节。因此，回复应该友好，并引导用户说明具体问题，以便更好地分类和回应。\n</think>您好！我是颐养医养结合养老机构的知识助手。您发送了测试消息，系统运行正常。请问您需要关于养老院管理方面的哪些帮助？例如入住流程优化、护理团队管理、医疗资源协调或数据分析建议等。请提供更多细节，我将为您针对性解答。','2026-04-19 18:51:14'),(41,1,'a3691917-17ac-4878-a479-bdb3a0070edb','查询id为1的老人健康档案','<think>\n好的，现在用户是admin，也就是管理员，他想要查询id为1的老人健康档案。首先，我需要根据角色设定来判断应该如何回应。根据规则，管理员可以得到管理层面的建议，所以我要确保回答符合他们的需求。\n\n首先，用户的问题是关于查询特定老人的健康档案。我需要确认系统中是否有这个功能或者是否需要调用某个工具。不过根据之前提供的工具列表，只有current_time这个工具，显然无法直接访问数据库或健康档案系统。因此，我需要告诉用户具体的步骤，而不是直接调用函数。\n\n接下来，我应该按照回答规则，管理员需要管理层面的建议，所以可能需要指导他们如何操作现有的系统或者流程来获取这些档案。例如，可能需要登录内部系统，输入ID搜索，或者联系相关医疗人员获取信息。同时要确保不涉及实际操作，只提供步骤说明。\n\n另外，用户可能需要确保数据的安全性和隐私保护，作为管理员，可能需要提醒他们确认权限是否足够，或者是否遵循了相关流程。不过用户的问题比较直接，可能只需要步骤。\n\n还要检查是否有可能需要调用其他工具，但根据提供的工具列表，没有相关函数可用，所以只能指导步骤。因此，回答应该包括建议登录内部管理系统，使用搜索功能，或者联系医疗部门，并提醒核对权限和隐私保护。这样既符合管理员角色的需求，也遵守了规则。\n</think>您好，关于查询老人健康档案，请按以下步骤操作：\n\n1. **系统登录**：请使用管理员账号登录机构内部管理系统（如EMR电子病历系统或养老档案管理平台）；\n2. **档案检索**：在搜索栏输入老人唯一标识ID「1」，选择「健康档案」分类进行精确查询；\n3. **权限确认**：若无法访问，请检查您的系统权限是否包含健康档案查阅模块；\n4. **数据安全**：根据隐私保护规定，请确保档案调阅行为符合机构数据管理规范。\n\n需要进一步协助可联系医疗数据管理员或提供具体系统界面问题描述。','2026-04-20 12:18:27'),(42,1,'a3691917-17ac-4878-a479-bdb3a0070edb','查询id为1的老人健康档案','<think>\n好的，用户再次询问了同样的问题：“查询id为1的老人健康档案”。之前已经回复过步骤，但用户再次提出，可能需要进一步确认或补充信息。\n\n首先，检查用户身份仍然是管理员，所以继续提供管理层面的指导。可能用户需要更详细的步骤，或者系统访问上的帮助。之前的回复已经提到了登录系统、搜索ID、确认权限和数据安全，但用户可能没有找到，或者需要其他途径。\n\n考虑到可能用户无法访问系统，或者需要其他方式获取数据。但根据工具限制，无法直接访问数据库，所以只能再次建议检查步骤，或者是否有其他障碍。另外，可能需要确认ID是否正确，或者是否有其他标识符（如姓名、房间号）可以辅助查询。\n\n此外，可能需要提醒用户联系技术部门或医疗记录管理员，如果系统出现故障或权限问题。同时，再次强调隐私保护的重要性，确保操作合规。\n\n可能用户希望得到更直接的数据，但根据规则，不能操作系统，只能指导步骤。因此，再次重复关键步骤，并询问是否需要其他帮助，比如具体系统界面的操作截图说明，或者是否有错误提示需要解析。\n</think>您好，根据您的角色（管理员），我提供以下操作指引：\n\n**获取健康档案的规范流程：**\n1. **系统访问验证**  \n   确认已登录机构核心管理系统（如金民工程系统/自建养老管理平台），并确保账号拥有「健康档案管理」权限模块。\n\n2. **精准检索方法**  \n   在顶部搜索栏输入 `ID:1` 后按「Enter」，或通过「档案管理→老年人信息→健康档案」路径进入，使用筛选器选择「ID=1」进行查询。\n\n3. **异常情况处理**  \n   - 若无检索结果：  \n     ▶ 检查ID是否为系统分配的唯一编码（非床位号/姓名缩写）  \n     ▶ 联系系统管理员核查档案是否处于归档/隔离状态  \n   - 若提示权限不足：  \n     ▶ 提交权限变更申请至机构IT部门（需注明业务场景）\n\n4. **数据导出与共享**  \n   点击档案右上角「导出」按钮可生成PDF/Excel文件，但需遵守《健康信息安全管理制度》第7条关于脱敏处理的规定。\n\n建议补充说明您的具体需求（如需查看某项指标历史记录/对比多期数据），以便提供更精准的操作建议。','2026-04-20 12:19:52'),(43,1,'c2079cf2-87be-4be5-92a3-ac391560b84c','用一个字介绍你','智智','2026-04-20 12:21:29'),(44,1,'c2079cf2-87be-4be5-92a3-ac391560b84c','你能干什么','我是颐养医养结合养老机构的**知识助手**，专为不同角色提供精准、实用的信息支持。具体来说：\n\n✅ **对管理员（如您当前角色 `admin`）：**  \n- 提供护理管理规范、排班优化建议、质量控制要点；  \n- 协助解读健康档案数据趋势，支持决策（如调取某位老人的健康记录分析）；  \n- 解答系统功能使用问题（如“如何查看全院失能老人分布？”）。\n\n✅ **对护工/医生/家属：**  \n- 护工：指导翻身频率、压疮预防操作、认知症老人沟通技巧等；  \n- 医生：提供慢病管理参考、用药注意事项、转诊评估要点；  \n- 家属：用通俗语言解释照护方案、疾病进展、医保政策等。\n\n? 当前您是 **管理员**，我可优先为您提供：  \n- 全院老人健康档案查询与分析支持（需提供老人ID）；  \n- 系统功能说明（如“如何导出月度护理质量报表？”）；  \n- 医养结合服务流程、标准依据（如《养老机构服务质量基本规范》要点）。\n\n需要我帮您做哪一类具体事情？例如：  \n? 查询某位老人的最新健康档案？  \n? 了解某项护理制度的执行要点？  \n? 查看系统中“跌倒风险评估”模块的操作说明？  \n\n欢迎随时告诉我 ?','2026-04-20 12:26:52'),(45,1,'c2079cf2-87be-4be5-92a3-ac391560b84c','查询id为1的老人档案','已成功查询到 **ID为1的老人（赵奶奶）** 的健康档案记录，信息如下：\n\n- ? **姓名**：赵奶奶  \n- ? **记录时间**：2025年12月15日（入院记录）  \n- ? **生命体征**：  \n  - 血压：130/86 mmHg（略偏高，舒张压临界，建议持续监测）  \n  - 心率：78 次/分（正常范围）  \n  - 体温：36.5℃（正常）  \n  - 血糖：6.20 mmol/L（空腹状态属正常上限，糖尿病老人需关注餐后波动）  \n  - 体重：62.30 kg（建议结合身高评估BMI，跟踪趋势）  \n- ? **症状描述**：精神良好，无不适  \n\n✅ **管理提示（面向管理员）**：  \n- 该记录为入院初评，建议核查是否已按规范完成**跌倒、压疮、认知、营养**四大风险评估并归档；  \n- 血压与血糖值虽在当前单次测量中未达危急值，但建议纳入**慢病管理台账**，设置定期复测提醒（如血压每周2次、空腹血糖每3天1次）；  \n- 系统更新时间为2026年4月13日，说明档案近期有维护，请确认是否已同步至护理计划系统。\n\n如需：  \n? 导出该档案为PDF用于家属沟通；  \n? 查询赵奶奶后续随访记录（如有更多ID关联记录）；  \n? 对比全院类似年龄/基础病老人的平均血压/血糖基线；  \n欢迎随时告知，我可进一步协助。','2026-04-20 12:28:32'),(46,1,'ec00af55-4924-4ef4-a3fd-8f997092e9cb','钱爷爷血压正常吗','为了判断钱爷爷的血压是否正常，我需要先查询他的健康档案。首先，我将通过姓名“钱爷爷”查询他的老人ID，然后获取其最新的健康记录。\n\n为了判断钱爷爷的血压是否正常，我需要先查询他的健康档案。首先，我将通过姓名“钱爷爷”查询他的老人ID，然后获取其最新的健康记录。\n\n为了判断钱爷爷的血压是否正常，我需要先查询他的健康档案。首先，我将通过姓名“钱爷爷”查询他的老人ID，然后获取其最新的健康记录。\n\n根据钱爷爷最新健康档案（记录时间：2026-03-10），其血压值为 **125/80 mmHg**，属于**正常血压范围**（参考标准：收缩压＜140 mmHg 且 舒张压＜90 mmHg）。\n\n补充说明：\n- 钱爷爷有“冠心病”基础病史，需持续关注血压波动趋势，避免清晨高血压或体位性变化引发风险；\n- 当前其他生命体征平稳：心率77次/分、体温36.6℃、空腹血糖5.90 mmol/L，均在适宜范围内；\n- 记录备注“精神良好，无不适”，提示整体状态稳定。\n\n✅ 建议（管理员视角）：\n- 将该数据同步至慢病管理台账，纳入冠心病老人月度血压趋势分析；\n- 提醒责任护工在晨间护理时规范测量并双人核对血压，尤其注意坐位/卧位差异；\n- 可结合医嘱评估是否需优化降压药物服药时间（如晨起服药 vs 睡前加量）。\n\n如需调取历史血压趋势图、生成慢病随访报表，或查看关联医嘱/用药记录，我可立即为您调用相应功能。根据钱爷爷最新健康档案（记录时间：2026-03-10），其血压值为 **125/80 mmHg**，属于**正常血压范围**（参考标准：收缩压＜140 mmHg 且 舒张压＜90 mmHg）。\n\n补充说明：\n- 钱爷爷有“冠心病”基础病史，需持续关注血压波动趋势，避免清晨高血压或体位性变化引发风险；\n- 当前其他生命体征平稳：心率77次/分、体温36.6℃、空腹血糖5.90 mmol/L，均在适宜范围内；\n- 记录备注“精神良好，无不适”，提示整体状态稳定。\n\n✅ 建议（管理员视角）：\n- 将该数据同步至慢病管理台账，纳入冠心病老人月度血压趋势分析；\n- 提醒责任护工在晨间护理时规范测量并双人核对血压，尤其注意坐位/卧位差异；\n- 可结合医嘱评估是否需优化降压药物服药时间（如晨起服药 vs 睡前加量）。\n\n如需调取历史血压趋势图、生成慢病随访报表，或查看关联医嘱/用药记录，我可立即为您调用相应功能。','2026-04-20 13:54:49'),(47,1,'ec00af55-4924-4ef4-a3fd-8f997092e9cb','简单描述一下赵奶奶的健康状况','为了准确描述赵奶奶的健康状况，我需要先通过她的姓名查询其老人ID，再调取最新的健康档案记录。\n\n为了准确描述赵奶奶的健康状况，我需要先通过她的姓名查询其老人ID，再调取最新的健康档案记录。\n\n为了准确描述赵奶奶的健康状况，我需要先通过她的姓名查询其老人ID，