/*Table structure for table `sys_nursing_home` */

DROP TABLE IF EXISTS `sys_nursing_home`;

CREATE TABLE `sys_nursing_home` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(255) NOT NULL COMMENT '养老院名称',
  `address` varchar(500) NOT NULL COMMENT '地址',
  `introduction` text COMMENT '介绍',
  `image_url` varchar(500) DEFAULT NULL COMMENT '展示图片URL',
  `contact_phone` varchar(20) DEFAULT NULL COMMENT '联系电话',
  `contact_person` varchar(50) DEFAULT NULL COMMENT '联系人',
  `establish_date` date DEFAULT NULL COMMENT '成立日期',
  `scale` varchar(100) DEFAULT NULL COMMENT '规模',
  `create_by` varchar(64) DEFAULT '' COMMENT '创建人',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) DEFAULT '' COMMENT '更新人',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(500) DEFAULT '' COMMENT '备注',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='养老院基本信息表';

