/*Table structure for table `sys_ward_round` */

DROP TABLE IF EXISTS `sys_ward_round`;

CREATE TABLE `sys_ward_round` (
  `round_id` bigint NOT NULL AUTO_INCREMENT COMMENT '查房记录ID',
  `room_id` bigint NOT NULL COMMENT '房间ID',
  `bed_id` bigint NOT NULL COMMENT '床位ID',
  `elderly_id` bigint NOT NULL COMMENT '老人ID',
  `round_time` datetime NOT NULL COMMENT '查房时间',
  `round_user_id` bigint NOT NULL COMMENT '查房人ID',
  `status` tinyint NOT NULL DEFAULT '0' COMMENT '查房状态：0-正常，1-异常',
  `abnormal_desc` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '异常描述',
  `handle_measure` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '处理措施',
  `image_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '查房图片URL',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '备注',
  `create_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '创建者',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '' COMMENT '更新者',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `del_flag` tinyint NOT NULL DEFAULT '0' COMMENT '删除标志：0-正常，1-删除',
  PRIMARY KEY (`round_id`),
  KEY `idx_room_bed` (`room_id`,`bed_id`),
  KEY `idx_elderly_time` (`elderly_id`,`round_time`),
  KEY `idx_round_user` (`round_user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='查房记录表';

/*Data for the table `sys_ward_round` */

